sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amplitudeX;
uniform float amplitudeY;
uniform float frequencyX;
uniform float frequencyY;
uniform float speed;
uniform float phase;
uniform float shape;
uniform float pin;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 uv = coord / size;
    float ax = uv.x * frequencyX * 6.2831853 + time * speed + radians(phase);
    float ay = uv.y * frequencyY * 6.2831853 + time * speed * 1.13 + radians(phase);
    float wx = sin(ax);
    float wy = sin(ay);
    if (shape > 0.5 && shape < 1.5) {
        wx = abs(fract(ax / 6.2831853) * 2.0 - 1.0) * 2.0 - 1.0;
        wy = abs(fract(ay / 6.2831853) * 2.0 - 1.0) * 2.0 - 1.0;
    } else if (shape > 1.5) {
        wx = clamp(sin(ax) * 3.0, -1.0, 1.0);
        wy = clamp(sin(ay) * 3.0, -1.0, 1.0);
    }
    float pinX = smoothstep(0.0, 0.2, uv.x) * (1.0 - smoothstep(0.8, 1.0, uv.x));
    float pinY = smoothstep(0.0, 0.2, uv.y) * (1.0 - smoothstep(0.8, 1.0, uv.y));
    float k = mix(1.0, pinX * pinY, pin);
    float4 r = tex(coord + float2(wy * amplitudeX, wx * amplitudeY) * k);
    return fin(c, r, opacity);
}
